UPDATE lessons SET title='Classification Writing: Group and Explain',data=json_patch(data,'{"seed_key":"s2-eng-y3-w07-l2","title":"Classification Writing: Group and Explain","stage":"Stage 2","learning_area":"English","year_level":3,"week":7,"lesson_number":2,"duration_minutes":60,"child_mission":"Learn classification writing: group and explain through original examples and guided practice before an independent challenge.","learning_intention":"We are learning to explain and apply classification writing: group and explain.","success_criteria":["I can explain the concept.","I can use and explain a worked example.","I can practise and learn from feedback.","I can attempt the independent challenge.","I can verify my answer."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Important concepts","cards":[{"front":"Choose a category","back":"A classification paragraph introduces how objects or living things are grouped, rather than telling an invented story."},{"front":"Find features shared within a group","back":"Use a distinguishing characteristic: adult butterflies have six legs and belong to insects; a skink has a backbone and is a reptile."},{"front":"Use examples as evidence","back":"A sentence can explain: ''For example, a butterfly is an insect because adults have six legs.'' Make the evidence relevant."},{"front":"Close with the grouping rule","back":"Finish: ''Body structures help us distinguish these garden animals.'' Avoid claiming they belong to the same group just because all live in a garden."}]}],"printable_resource":{"title":"Classification Writing: Group and Explain","instructions":"Use the original example to learn, then solve the new task.","passage":"Skinks are reptiles; butterflies are insects; earthworms are segmented invertebrates.","prompts":["Find evidence.","Explain the method.","Try the new task.","Check it."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Choose a category","explain":"**Learn this idea:** A classification paragraph introduces how objects or living things are grouped, rather than telling an invented story.\n\n**Original source:** Skinks are reptiles; butterflies are insects; earthworms are segmented invertebrates.\n\nLook for the specific clue or number that proves your conclusion.","example":"**WATCH MY THINKING:** A classification paragraph introduces how objects or living things are grouped, rather than telling an invented story.\n\n**TRY:** Draft an 90–130 word classification paragraph using these facts: a bee is an insect with six adult legs; a magpie is a bird with feathers; a blue-tongue skink is a reptile with scales and a backbone. Use a topic sentence, three explained examples and a closing sentence.\n\n**CHECK:** Compare your method against the original case and correct any mistaken detail.","notice":"A classification paragraph introduces how objects or living things are grouped, rather than telling an invented story.","check":{"question":"Which is a classification opening?","options":["Garden animals belong to different groups.","Once upon a time","Suddenly a thief arrived","I bought a book"],"correct_index":0,"explanation":"Garden animals belong to different groups.: A classification paragraph introduces how objects or living things are grouped, rather than telling an invented story."},"visual_before":[{"episode":{"title":"Classification Writing: Group and Explain: first clue","transcript":"Pip: Do all animals in one garden belong to the same group?\nJuno: No. Classify by body features, not only by where they live.\nPip: Bees are insects; magpies are birds, and skinks are reptiles.\nJuno: Pause and name one identifying feature for each.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"Do all animals in one garden belong to the same group?"},{"who":"juno","text":"No. Classify by body features, not only by where they live."},{"who":"pip","text":"Bees are insects; magpies are birds, and skinks are reptiles."},{"who":"juno","text":"Pause and name one identifying feature for each.","pause_after":true}]}]}}]},{"icon":"📘","title":"Find features shared within a group","explain":"**Learn this idea:** Use a distinguishing characteristic: adult butterflies have six legs and belong to insects; a skink has a backbone and is a reptile.\n\n**Original source:** Skinks are reptiles; butterflies are insects; earthworms are segmented invertebrates.\n\nLook for the specific clue or number that proves your conclusion.","example":"**WATCH MY THINKING:** Use a distinguishing characteristic: adult butterflies have six legs and belong to insects; a skink has a backbone and is a reptile.\n\n**TRY:** Draft an 90–130 word classification paragraph using these facts: a bee is an insect with six adult legs; a magpie is a bird with feathers; a blue-tongue skink is a reptile with scales and a backbone. Use a topic sentence, three explained examples and a closing sentence.\n\n**CHECK:** Compare your method against the original case and correct any mistaken detail.","notice":"Use a distinguishing characteristic: adult butterflies have six legs and belong to insects; a skink has a backbone and is a reptile.","check":{"question":"Which is an insect?","options":["Blue-tongue skink","Bee","Magpie","Earthworm"],"correct_index":1,"explanation":"Bee: Use a distinguishing characteristic: adult butterflies have six legs and belong to insects; a skink has a backbone and is a reptile."}},{"icon":"✍️","title":"Use examples as evidence","explain":"**Learn this idea:** A sentence can explain: ''For example, a butterfly is an insect because adults have six legs.'' Make the evidence relevant.\n\n**Original source:** Skinks are reptiles; butterflies are insects; earthworms are segmented invertebrates.\n\nLook for the specific clue or number that proves your conclusion.","example":"**WATCH MY THINKING:** A sentence can explain: ''For example, a butterfly is an insect because adults have six legs.'' Make the evidence relevant.\n\n**TRY:** Draft an 90–130 word classification paragraph using these facts: a bee is an insect with six adult legs; a magpie is a bird with feathers; a blue-tongue skink is a reptile with scales and a backbone. Use a topic sentence, three explained examples and a closing sentence.\n\n**CHECK:** Compare your method against the original case and correct any mistaken detail.","notice":"A sentence can explain: ''For example, a butterfly is an insect because adults have six legs.'' Make the evidence relevant.","check":{"question":"Which has feathers?","options":["Magpie","Bee","Skink","Butterfly"],"correct_index":0,"explanation":"Magpie: A sentence can explain: ''For example, a butterfly is an insect because adults have six legs.'' Make the evidence relevant."}},{"icon":"✅","title":"Close with the grouping rule","explain":"**Learn this idea:** Finish: ''Body structures help us distinguish these garden animals.'' Avoid claiming they belong to the same group just because all live in a garden.\n\n**Original source:** Skinks are reptiles; butterflies are insects; earthworms are segmented invertebrates.\n\nLook for the specific clue or number that proves your conclusion.","example":"**WATCH MY THINKING:** Finish: ''Body structures help us distinguish these garden animals.'' Avoid claiming they belong to the same group just because all live in a garden.\n\n**TRY:** Draft an 90–130 word classification paragraph using these facts: a bee is an insect with six adult legs; a magpie is a bird with feathers; a blue-tongue skink is a reptile with scales and a backbone. Use a topic sentence, three explained examples and a closing sentence.\n\n**CHECK:** Compare your method against the original case and correct any mistaken detail.","notice":"Finish: ''Body structures help us distinguish these garden animals.'' Avoid claiming they belong to the same group just because all live in a garden.","check":{"question":"What identifies the adult bee?","options":["Six legs","Eight legs","Feathers","A backbone"],"correct_index":0,"explanation":"Six legs: Finish: ''Body structures help us distinguish these garden animals.'' Avoid claiming they belong to the same group just because all live in a garden."}}],"worked_example":"Skinks are reptiles; butterflies are insects; earthworms are segmented invertebrates.\n\n**1. Choose a category:** A classification paragraph introduces how objects or living things are grouped, rather than telling an invented story.\n\n**2. Find features shared within a group:** Use a distinguishing characteristic: adult butterflies have six legs and belong to insects; a skink has a backbone and is a reptile.\n\n**3. Use examples as evidence:** A sentence can explain: ''For example, a butterfly is an insect because adults have six legs.'' Make the evidence relevant.\n\n**4. Close with the grouping rule:** Finish: ''Body structures help us distinguish these garden animals.'' Avoid claiming they belong to the same group just because all live in a garden.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 540 170\"><rect width=\"540\" height=\"170\" rx=\"10\" fill=\"#f4f8f5\"/><text x=\"12\" y=\"30\" font-family=\"Arial\" font-size=\"20\">Classification steps</text><rect x=\"8\" y=\"55\" width=\"126\" height=\"95\" rx=\"8\" fill=\"#deede3\"/><text x=\"20\" y=\"103\" font-family=\"Arial\" font-size=\"16\">FIND</text><rect x=\"142\" y=\"55\" width=\"126\" height=\"95\" rx=\"8\" fill=\"#e8ecf7\"/><text x=\"154\" y=\"103\" font-family=\"Arial\" font-size=\"16\">EXPLAIN</text><rect x=\"276\" y=\"55\" width=\"126\" height=\"95\" rx=\"8\" fill=\"#deede3\"/><text x=\"288\" y=\"103\" font-family=\"Arial\" font-size=\"16\">TRY</text><rect x=\"410\" y=\"55\" width=\"126\" height=\"95\" rx=\"8\" fill=\"#e8ecf7\"/><text x=\"422\" y=\"103\" font-family=\"Arial\" font-size=\"16\">CHECK</text></svg>","alt":"A four-part method for Classification Writing: Group and Explain.","caption":"Find, explain, try and check."}],"guided_practice":"First read the model carefully: A classification paragraph introduces how objects or living things are grouped, rather than telling an invented story. Use a distinguishing characteristic: adult butterflies have six legs and belong to insects; a skink has a backbone and is a reptile. A sentence can explain: ''For example, a butterfly is an insect because adults have six legs.'' Make the evidence relevant. Finish: ''Body structures help us distinguish these garden animals.'' Avoid claiming they belong to the same group just because all live in a garden.\n\nTry a case from the new challenge and use this feedback to revise your attempt: My topic sentence introduces classifications. My supporting sentences each connect one feature to a category. I avoid claiming all garden animals are insects.","independent_task":"Draft an 90–130 word classification paragraph using these facts: a bee is an insect with six adult legs; a magpie is a bird with feathers; a blue-tongue skink is a reptile with scales and a backbone. Use a topic sentence, three explained examples and a closing sentence.","response_prompt":"Draft an 90–130 word classification paragraph using these facts: a bee is an insect with six adult legs; a magpie is a bird with feathers; a blue-tongue skink is a reptile with scales and a backbone. Use a topic sentence, three explained examples and a closing sentence.","quiz":[{"type":"multiple_choice","question":"Which is a classification opening?","options":["Garden animals belong to different groups.","Once upon a time","Suddenly a thief arrived","I bought a book"],"correct_index":0,"explanation":"Garden animals belong to different groups. follows the original source and teaching."},{"type":"multiple_choice","question":"Which is an insect?","options":["Blue-tongue skink","Bee","Magpie","Earthworm"],"correct_index":1,"explanation":"Bee follows the original source and teaching."},{"type":"multiple_choice","question":"Which has feathers?","options":["Magpie","Bee","Skink","Butterfly"],"correct_index":0,"explanation":"Magpie follows the original source and teaching."},{"type":"multiple_choice","question":"What identifies the adult bee?","options":["Six legs","Eight legs","Feathers","A backbone"],"correct_index":0,"explanation":"Six legs follows the original source and teaching."},{"type":"multiple_choice","question":"Which is a reptile?","options":["Bee","Magpie","Skink","Butterfly"],"correct_index":2,"explanation":"Skink follows the original source and teaching."},{"type":"multiple_choice","question":"Which connector introduces evidence?","options":["For example","Suddenly","Never again","The end"],"correct_index":0,"explanation":"For example follows the original source and teaching."},{"type":"multiple_choice","question":"What should a closing sentence do?","options":["Connect the grouping ideas","Introduce a new unrelated villain","Repeat every sentence","Change the subject"],"correct_index":0,"explanation":"Connect the grouping ideas follows the original source and teaching."},{"type":"multiple_choice","question":"Which claim is unsupported?","options":["Bees are insects","Magpies are birds","All garden animals are insects","Skinks are reptiles"],"correct_index":2,"explanation":"All garden animals are insects follows the original source and teaching."},{"type":"short_answer","question":"Complete the original classification writing: group and explain challenge.","sample_answer":"Bees are insects with six legs as adults; magpies are birds with feathers; skinks are reptiles with scales and backbones. These different body structures help identify groups.","marking_guide":"Look for accurate task-specific evidence and a clear explanation.","explanation":"A complete answer demonstrates the method."},{"type":"short_answer","question":"Explain a specific correction or verification method.","sample_answer":"My topic sentence introduces classifications. My supporting sentences each connect one feature to a category. I avoid claiming all garden animals are insects.","marking_guide":"Require relevant detail and correct reasoning.","explanation":"Show why the conclusion follows."}],"parent_notes":"Parent: Ask the learner to show the independent work and explain their reasoning.\n\nParent: Written model 1: Bees are insects with six legs as adults; magpies are birds with feathers; skinks are reptiles with scales and backbones. These different body structures help identify groups.\n\nParent: Written model 2: My topic sentence introduces classifications. My supporting sentences each connect one feature to a category. I avoid claiming all garden animals are insects.\n\nParent: Verify answers, retain evidence and check curriculum alignment separately.","evidence_instructions":"Keep your guided and independent work, along with one correction and written quiz responses.","offline_alternative":"Complete the included examples and challenge on paper; a parent can record oral responses.","extension":"Make a new classification writing: group and explain challenge and explain the answer.","stage_hints":{"accept":["Read the Classification Writing: Group and Explain instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"teach0":["Read the Choose a category instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"teach1":["Read the Find features shared within a group instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"teach2":["Read the Use examples as evidence instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"teach3":["Read the Close with the grouping rule instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"learn":["Read the Classification Writing: Group and Explain instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"guided":["Read the Classification Writing: Group and Explain instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"write":["Read the Classification Writing: Group and Explain instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"quiz":["Read the Classification Writing: Group and Explain instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"submit":["Read the Classification Writing: Group and Explain instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."]}}') WHERE seed_key='s2-eng-y3-w07-l2';
UPDATE lessons SET title='Pronouns and Cohesion: Clear References',data=json_patch(data,'{"seed_key":"s2-eng-y3-w07-l3","title":"Pronouns and Cohesion: Clear References","stage":"Stage 2","learning_area":"English","year_level":3,"week":7,"lesson_number":3,"duration_minutes":60,"child_mission":"Learn pronouns and cohesion: clear references through original examples and guided practice before an independent challenge.","learning_intention":"We are learning to explain and apply pronouns and cohesion: clear references.","success_criteria":["I can explain the concept.","I can use and explain a worked example.","I can practise and learn from feedback.","I can attempt the independent challenge.","I can verify my answer."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Important concepts","cards":[{"front":"Find the noun being replaced","back":"In ''Lena planted a seed'', Lena is a person and seed is a thing. ''She'' can refer to Lena; ''it'' can refer to the seed."},{"front":"Match pronouns to nouns","back":"Rewrite ''Lena watered the seed'' as ''She watered it.'' The reader can still identify the person and object."},{"front":"Avoid ambiguous references","back":"''Mia spoke to Ava when she arrived'' is unclear because she could mean either person. Write ''When Ava arrived, Mia spoke to her.''"},{"front":"Revise a paragraph for flow","back":"A cohesive version is ''Lena planted a seed. She watered it and placed it near the window.'' Check each pronoun''s referent."}]}],"printable_resource":{"title":"Pronouns and Cohesion: Clear References","instructions":"Use the original example to learn, then solve the new task.","passage":"Lena planted a seed. Lena watered the seed. Lena placed the seed on a windowsill.","prompts":["Find evidence.","Explain the method.","Try the new task.","Check it."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Find the noun being replaced","explain":"**Learn this idea:** In ''Lena planted a seed'', Lena is a person and seed is a thing. ''She'' can refer to Lena; ''it'' can refer to the seed.\n\n**Original source:** Lena planted a seed. Lena watered the seed. Lena placed the seed on a windowsill.\n\nLook for the specific clue or number that proves your conclusion.","example":"**WATCH MY THINKING:** In ''Lena planted a seed'', Lena is a person and seed is a thing. ''She'' can refer to Lena; ''it'' can refer to the seed.\n\n**TRY:** Rewrite: ''Ari and Beau made a birdhouse. Ari painted the birdhouse. Beau carried the birdhouse to the fence. Ari and Beau placed the birdhouse on a post.'' Use three different pronouns with clear references. Explain what each replaces. Rewrite ''Ari told Beau that they had lost the brush'' to remove ambiguity.\n\n**CHECK:** Compare your method against the original case and correct any mistaken detail.","notice":"In ''Lena planted a seed'', Lena is a person and seed is a thing. ''She'' can refer to Lena; ''it'' can refer to the seed.","check":{"question":"What can replace Lena?","options":["she","they for two people","it","those"],"correct_index":0,"explanation":"she: In ''Lena planted a seed'', Lena is a person and seed is a thing. ''She'' can refer to Lena; ''it'' can refer to the seed."},"visual_before":[{"episode":{"title":"Pronouns and Cohesion: Clear References: first clue","transcript":"Pip: Lena planted a seed. Lena watered the seed. That repeats!\nJuno: Replace Lena with she and seed with it, while keeping references clear.\nPip: She watered it. I can still tell who and what.\nJuno: Pause and explain what each pronoun refers to.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"Lena planted a seed. Lena watered the seed. That repeats!"},{"who":"juno","text":"Replace Lena with she and seed with it, while keeping references clear."},{"who":"pip","text":"She watered it. I can still tell who and what."},{"who":"juno","text":"Pause and explain what each pronoun refers to.","pause_after":true}]}]}}]},{"icon":"📘","title":"Match pronouns to nouns","explain":"**Learn this idea:** Rewrite ''Lena watered the seed'' as ''She watered it.'' The reader can still identify the person and object.\n\n**Original source:** Lena planted a seed. Lena watered the seed. Lena placed the seed on a windowsill.\n\nLook for the specific clue or number that proves your conclusion.","example":"**WATCH MY THINKING:** Rewrite ''Lena watered the seed'' as ''She watered it.'' The reader can still identify the person and object.\n\n**TRY:** Rewrite: ''Ari and Beau made a birdhouse. Ari painted the birdhouse. Beau carried the birdhouse to the fence. Ari and Beau placed the birdhouse on a post.'' Use three different pronouns with clear references. Explain what each replaces. Rewrite ''Ari told Beau that they had lost the brush'' to remove ambiguity.\n\n**CHECK:** Compare your method against the original case and correct any mistaken detail.","notice":"Rewrite ''Lena watered the seed'' as ''She watered it.'' The reader can still identify the person and object.","check":{"question":"What does it replace in ''She watered it''?","options":["Lena","the seed","the window","the waterer"],"correct_index":1,"explanation":"the seed: Rewrite ''Lena watered the seed'' as ''She watered it.'' The reader can still identify the person and object."}},{"icon":"✍️","title":"Avoid ambiguous references","explain":"**Learn this idea:** ''Mia spoke to Ava when she arrived'' is unclear because she could mean either person. Write ''When Ava arrived, Mia spoke to her.''\n\n**Original source:** Lena planted a seed. Lena watered the seed. Lena placed the seed on a windowsill.\n\nLook for the specific clue or number that proves your conclusion.","example":"**WATCH MY THINKING:** ''Mia spoke to Ava when she arrived'' is unclear because she could mean either person. Write ''When Ava arrived, Mia spoke to her.''\n\n**TRY:** Rewrite: ''Ari and Beau made a birdhouse. Ari painted the birdhouse. Beau carried the birdhouse to the fence. Ari and Beau placed the birdhouse on a post.'' Use three different pronouns with clear references. Explain what each replaces. Rewrite ''Ari told Beau that they had lost the brush'' to remove ambiguity.\n\n**CHECK:** Compare your method against the original case and correct any mistaken detail.","notice":"''Mia spoke to Ava when she arrived'' is unclear because she could mean either person. Write ''When Ava arrived, Mia spoke to her.''","check":{"question":"Which plural pronoun matches Ari and Beau?","options":["it","they","she","him"],"correct_index":1,"explanation":"they: ''Mia spoke to Ava when she arrived'' is unclear because she could mean either person. Write ''When Ava arrived, Mia spoke to her.''"}},{"icon":"✅","title":"Revise a paragraph for flow","explain":"**Learn this idea:** A cohesive version is ''Lena planted a seed. She watered it and placed it near the window.'' Check each pronoun''s referent.\n\n**Original source:** Lena planted a seed. Lena watered the seed. Lena placed the seed on a windowsill.\n\nLook for the specific clue or number that proves your conclusion.","example":"**WATCH MY THINKING:** A cohesive version is ''Lena planted a seed. She watered it and placed it near the window.'' Check each pronoun''s referent.\n\n**TRY:** Rewrite: ''Ari and Beau made a birdhouse. Ari painted the birdhouse. Beau carried the birdhouse to the fence. Ari and Beau placed the birdhouse on a post.'' Use three different pronouns with clear references. Explain what each replaces. Rewrite ''Ari told Beau that they had lost the brush'' to remove ambiguity.\n\n**CHECK:** Compare your method against the original case and correct any mistaken detail.","notice":"A cohesive version is ''Lena planted a seed. She watered it and placed it near the window.'' Check each pronoun''s referent.","check":{"question":"Which sentence is unclear?","options":["The seed grew.","Mia spoke to Ava when she arrived.","Lena watered a plant.","Beau built a birdhouse."],"correct_index":1,"explanation":"Mia spoke to Ava when she arrived.: A cohesive version is ''Lena planted a seed. She watered it and placed it near the window.'' Check each pronoun''s referent."}}],"worked_example":"Lena planted a seed. Lena watered the seed. Lena placed the seed on a windowsill.\n\n**1. Find the noun being replaced:** In ''Lena planted a seed'', Lena is a person and seed is a thing. ''She'' can refer to Lena; ''it'' can refer to the seed.\n\n**2. Match pronouns to nouns:** Rewrite ''Lena watered the seed'' as ''She watered it.'' The reader can still identify the person and object.\n\n**3. Avoid ambiguous references:** ''Mia spoke to Ava when she arrived'' is unclear because she could mean either person. Write ''When Ava arrived, Mia spoke to her.''\n\n**4. Revise a paragraph for flow:** A cohesive version is ''Lena planted a seed. She watered it and placed it near the window.'' Check each pronoun''s referent.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 540 170\"><rect width=\"540\" height=\"170\" rx=\"10\" fill=\"#f4f8f5\"/><text x=\"12\" y=\"30\" font-family=\"Arial\" font-size=\"20\">Pronouns and nouns</text><rect x=\"8\" y=\"55\" width=\"126\" height=\"95\" rx=\"8\" fill=\"#deede3\"/><text x=\"20\" y=\"103\" font-family=\"Arial\" font-size=\"16\">FIND</text><rect x=\"142\" y=\"55\" width=\"126\" height=\"95\" rx=\"8\" fill=\"#e8ecf7\"/><text x=\"154\" y=\"103\" font-family=\"Arial\" font-size=\"16\">EXPLAIN</text><rect x=\"276\" y=\"55\" width=\"126\" height=\"95\" rx=\"8\" fill=\"#deede3\"/><text x=\"288\" y=\"103\" font-family=\"Arial\" font-size=\"16\">TRY</text><rect x=\"410\" y=\"55\" width=\"126\" height=\"95\" rx=\"8\" fill=\"#e8ecf7\"/><text x=\"422\" y=\"103\" font-family=\"Arial\" font-size=\"16\">CHECK</text></svg>","alt":"A four-part method for Pronouns and Cohesion: Clear References.","caption":"Find, explain, try and check."}],"guided_practice":"First read the model carefully: In ''Lena planted a seed'', Lena is a person and seed is a thing. ''She'' can refer to Lena; ''it'' can refer to the seed. Rewrite ''Lena watered the seed'' as ''She watered it.'' The reader can still identify the person and object. ''Mia spoke to Ava when she arrived'' is unclear because she could mean either person. Write ''When Ava arrived, Mia spoke to her.'' A cohesive version is ''Lena planted a seed. She watered it and placed it near the window.'' Check each pronoun''s referent.\n\nTry a case from the new challenge and use this feedback to revise your attempt: ''Ari told Beau, “I lost the brush.”'' identifies Ari as the speaker and person who lost it. A pronoun is helpful only when its meaning is clear.","independent_task":"Rewrite: ''Ari and Beau made a birdhouse. Ari painted the birdhouse. Beau carried the birdhouse to the fence. Ari and Beau placed the birdhouse on a post.'' Use three different pronouns with clear references. Explain what each replaces. Rewrite ''Ari told Beau that they had lost the brush'' to remove ambiguity.","response_prompt":"Rewrite: ''Ari and Beau made a birdhouse. Ari painted the birdhouse. Beau carried the birdhouse to the fence. Ari and Beau placed the birdhouse on a post.'' Use three different pronouns with clear references. Explain what each replaces. Rewrite ''Ari told Beau that they had lost the brush'' to remove ambiguity.","quiz":[{"type":"multiple_choice","question":"What can replace Lena?","options":["she","they for two people","it","those"],"correct_index":0,"explanation":"she follows the original source and teaching."},{"type":"multiple_choice","question":"What does it replace in ''She watered it''?","options":["Lena","the seed","the window","the waterer"],"correct_index":1,"explanation":"the seed follows the original source and teaching."},{"type":"multiple_choice","question":"Which plural pronoun matches Ari and Beau?","options":["it","they","she","him"],"correct_index":1,"explanation":"they follows the original source and teaching."},{"type":"multiple_choice","question":"Which sentence is unclear?","options":["The seed grew.","Mia spoke to Ava when she arrived.","Lena watered a plant.","Beau built a birdhouse."],"correct_index":1,"explanation":"Mia spoke to Ava when she arrived. follows the original source and teaching."},{"type":"multiple_choice","question":"What does cohesion mean?","options":["Clear links across sentences","Random repetition","Only longer words","Perfect handwriting"],"correct_index":0,"explanation":"Clear links across sentences follows the original source and teaching."},{"type":"multiple_choice","question":"Which pronoun replaces two books?","options":["it","them","him","one"],"correct_index":1,"explanation":"them follows the original source and teaching."},{"type":"multiple_choice","question":"When should a name be repeated?","options":["When a pronoun is ambiguous","Never","Only in a heading","Whenever a sentence has a comma"],"correct_index":0,"explanation":"When a pronoun is ambiguous follows the original source and teaching."},{"type":"multiple_choice","question":"Which is clear?","options":["Ari painted the birdhouse. Beau carried it.","She told her about it.","They did it there.","It said they did this."],"correct_index":0,"explanation":"Ari painted the birdhouse. Beau carried it. follows the original source and teaching."},{"type":"short_answer","question":"Complete the original pronouns and cohesion: clear references challenge.","sample_answer":"Ari and Beau made a birdhouse. Ari painted it; Beau carried it to the fence. They placed it on a post. ''It'' refers to the birdhouse and ''they'' to Ari and Beau.","marking_guide":"Look for accurate task-specific evidence and a clear explanation.","explanation":"A complete answer demonstrates the method."},{"type":"short_answer","question":"Explain a specific correction or verification method.","sample_answer":"''Ari told Beau, “I lost the brush.”'' identifies Ari as the speaker and person who lost it. A pronoun is helpful only when its meaning is clear.","marking_guide":"Require relevant detail and correct reasoning.","explanation":"Show why the conclusion follows."}],"parent_notes":"Parent: Ask the learner to show the independent work and explain their reasoning.\n\nParent: Written model 1: Ari and Beau made a birdhouse. Ari painted it; Beau carried it to the fence. They placed it on a post. ''It'' refers to the birdhouse and ''they'' to Ari and Beau.\n\nParent: Written model 2: ''Ari told Beau, “I lost the brush.”'' identifies Ari as the speaker and person who lost it. A pronoun is helpful only when its meaning is clear.\n\nParent: Verify answers, retain evidence and check curriculum alignment separately.","evidence_instructions":"Keep your guided and independent work, along with one correction and written quiz responses.","offline_alternative":"Complete the included examples and challenge on paper; a parent can record oral responses.","extension":"Make a new pronouns and cohesion: clear references challenge and explain the answer.","stage_hints":{"accept":["Read the Pronouns and Cohesion: Clear References instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"teach0":["Read the Find the noun being replaced instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"teach1":["Read the Match pronouns to nouns instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"teach2":["Read the Avoid ambiguous references instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"teach3":["Read the Revise a paragraph for flow instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"learn":["Read the Pronouns and Cohesion: Clear References instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"guided":["Read the Pronouns and Cohesion: Clear References instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"write":["Read the Pronouns and Cohesion: Clear References instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"quiz":["Read the Pronouns and Cohesion: Clear References instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"submit":["Read the Pronouns and Cohesion: Clear References instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."]}}') WHERE seed_key='s2-eng-y3-w07-l3';
UPDATE lessons SET title='Source Sleuth: Check Evidence and Claims',data=json_patch(data,'{"seed_key":"s2-eng-y3-w07-l4","title":"Source Sleuth: Check Evidence and Claims","stage":"Stage 2","learning_area":"English","year_level":3,"week":7,"lesson_number":4,"duration_minutes":60,"child_mission":"Learn source sleuth: check evidence and claims through original examples and guided practice before an independent challenge.","learning_intention":"We are learning to explain and apply source sleuth: check evidence and claims.","success_criteria":["I can explain the concept.","I can use and explain a worked example.","I can practise and learn from feedback.","I can attempt the independent challenge.","I can verify my answer."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Important concepts","cards":[{"front":"Identify a source and its claim","back":"A source is where information comes from. Record exactly what each source claims before evaluating it."},{"front":"Find accountable authorship","back":"A named specialist team and examples are useful credibility clues. An anonymous caption does not supply expertise or proof."},{"front":"Compare evidence rather than volume","back":"Absolute statements such as ''all bees'' need checking. Compare them with relevant, evidenced sources instead of the loudest post."},{"front":"Make qualified conclusions","back":"Say ''This named fact sheet is a stronger starting source'' rather than ''It can never be wrong''. Check information independently."}]}],"printable_resource":{"title":"Source Sleuth: Check Evidence and Claims","instructions":"Use the original example to learn, then solve the new task.","passage":"A named biodiversity team''s fact sheet gives examples of native-bee nesting places. An anonymous video claims all bees live in giant hives without evidence.","prompts":["Find evidence.","Explain the method.","Try the new task.","Check it."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Identify a source and its claim","explain":"**Learn this idea:** A source is where information comes from. Record exactly what each source claims before evaluating it.\n\n**Original source:** A named biodiversity team''s fact sheet gives examples of native-bee nesting places. An anonymous video claims all bees live in giant hives without evidence.\n\nLook for the specific clue or number that proves your conclusion.","example":"**WATCH MY THINKING:** A source is where information comes from. Record exactly what each source claims before evaluating it.\n\n**TRY:** Compare three fictional cards: biodiversity team''s illustrated bee nesting guide; anonymous ''ALL bees live in giant hives'' caption; gardener who reports seeing a bee in a hollow stem. Rank usefulness for broad information, identify an observation, explain two credibility clues and a claim that needs checking.\n\n**CHECK:** Compare your method against the original case and correct any mistaken detail.","notice":"A source is where information comes from. Record exactly what each source claims before evaluating it.","check":{"question":"Which has identifiable authorship?","options":["Biodiversity team","Anonymous caption","Unlabelled screenshot","Unknown rumour"],"correct_index":0,"explanation":"Biodiversity team: A source is where information comes from. Record exactly what each source claims before evaluating it."},"visual_before":[{"episode":{"title":"Source Sleuth: Check Evidence and Claims: first clue","transcript":"Pip: This anonymous post says all bees live in giant hives!\nJuno: Look for a responsible author and evidence before accepting that claim.\nPip: A named biodiversity team offers examples I can check.\nJuno: Pause and say why one gardener''s observation cannot prove a rule for every bee.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"This anonymous post says all bees live in giant hives!"},{"who":"juno","text":"Look for a responsible author and evidence before accepting that claim."},{"who":"pip","text":"A named biodiversity team offers examples I can check."},{"who":"juno","text":"Pause and say why one gardener''s observation cannot prove a rule for every bee.","pause_after":true}]}]}}]},{"icon":"📘","title":"Find accountable authorship","explain":"**Learn this idea:** A named specialist team and examples are useful credibility clues. An anonymous caption does not supply expertise or proof.\n\n**Original source:** A named biodiversity team''s fact sheet gives examples of native-bee nesting places. An anonymous video claims all bees live in giant hives without evidence.\n\nLook for the specific clue or number that proves your conclusion.","example":"**WATCH MY THINKING:** A named specialist team and examples are useful credibility clues. An anonymous caption does not supply expertise or proof.\n\n**TRY:** Compare three fictional cards: biodiversity team''s illustrated bee nesting guide; anonymous ''ALL bees live in giant hives'' caption; gardener who reports seeing a bee in a hollow stem. Rank usefulness for broad information, identify an observation, explain two credibility clues and a claim that needs checking.\n\n**CHECK:** Compare your method against the original case and correct any mistaken detail.","notice":"A named specialist team and examples are useful credibility clues. An anonymous caption does not supply expertise or proof.","check":{"question":"What helps check a claim?","options":["Examples and evidence","Capital letters","Lots of exclamation marks","Anonymity"],"correct_index":0,"explanation":"Examples and evidence: A named specialist team and examples are useful credibility clues. An anonymous caption does not supply expertise or proof."}},{"icon":"✍️","title":"Compare evidence rather than volume","explain":"**Learn this idea:** Absolute statements such as ''all bees'' need checking. Compare them with relevant, evidenced sources instead of the loudest post.\n\n**Original source:** A named biodiversity team''s fact sheet gives examples of native-bee nesting places. An anonymous video claims all bees live in giant hives without evidence.\n\nLook for the specific clue or number that proves your conclusion.","example":"**WATCH MY THINKING:** Absolute statements such as ''all bees'' need checking. Compare them with relevant, evidenced sources instead of the loudest post.\n\n**TRY:** Compare three fictional cards: biodiversity team''s illustrated bee nesting guide; anonymous ''ALL bees live in giant hives'' caption; gardener who reports seeing a bee in a hollow stem. Rank usefulness for broad information, identify an observation, explain two credibility clues and a claim that needs checking.\n\n**CHECK:** Compare your method against the original case and correct any mistaken detail.","notice":"Absolute statements such as ''all bees'' need checking. Compare them with relevant, evidenced sources instead of the loudest post.","check":{"question":"Which is a sweeping claim?","options":["Every bee lives in a hive","A gardener saw one bee","Some bees visit flowers","A source includes pictures"],"correct_index":0,"explanation":"Every bee lives in a hive: Absolute statements such as ''all bees'' need checking. Compare them with relevant, evidenced sources instead of the loudest post."}},{"icon":"✅","title":"Make qualified conclusions","explain":"**Learn this idea:** Say ''This named fact sheet is a stronger starting source'' rather than ''It can never be wrong''. Check information independently.\n\n**Original source:** A named biodiversity team''s fact sheet gives examples of native-bee nesting places. An anonymous video claims all bees live in giant hives without evidence.\n\nLook for the specific clue or number that proves your conclusion.","example":"**WATCH MY THINKING:** Say ''This named fact sheet is a stronger starting source'' rather than ''It can never be wrong''. Check information independently.\n\n**TRY:** Compare three fictional cards: biodiversity team''s illustrated bee nesting guide; anonymous ''ALL bees live in giant hives'' caption; gardener who reports seeing a bee in a hollow stem. Rank usefulness for broad information, identify an observation, explain two credibility clues and a claim that needs checking.\n\n**CHECK:** Compare your method against the original case and correct any mistaken detail.","notice":"Say ''This named fact sheet is a stronger starting source'' rather than ''It can never be wrong''. Check information independently.","check":{"question":"Which is an observation?","options":["One bee entered a stem","All bees always nest in hives","An invented rule","A guessed global total"],"correct_index":0,"explanation":"One bee entered a stem: Say ''This named fact sheet is a stronger starting source'' rather than ''It can never be wrong''. Check information independently."}}],"worked_example":"A named biodiversity team''s fact sheet gives examples of native-bee nesting places. An anonymous video claims all bees live in giant hives without evidence.\n\n**1. Identify a source and its claim:** A source is where information comes from. Record exactly what each source claims before evaluating it.\n\n**2. Find accountable authorship:** A named specialist team and examples are useful credibility clues. An anonymous caption does not supply expertise or proof.\n\n**3. Compare evidence rather than volume:** Absolute statements such as ''all bees'' need checking. Compare them with relevant, evidenced sources instead of the loudest post.\n\n**4. Make qualified conclusions:** Say ''This named fact sheet is a stronger starting source'' rather than ''It can never be wrong''. Check information independently.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 540 170\"><rect width=\"540\" height=\"170\" rx=\"10\" fill=\"#f4f8f5\"/><text x=\"12\" y=\"30\" font-family=\"Arial\" font-size=\"20\">Source checks</text><rect x=\"8\" y=\"55\" width=\"126\" height=\"95\" rx=\"8\" fill=\"#deede3\"/><text x=\"20\" y=\"103\" font-family=\"Arial\" font-size=\"16\">FIND</text><rect x=\"142\" y=\"55\" width=\"126\" height=\"95\" rx=\"8\" fill=\"#e8ecf7\"/><text x=\"154\" y=\"103\" font-family=\"Arial\" font-size=\"16\">EXPLAIN</text><rect x=\"276\" y=\"55\" width=\"126\" height=\"95\" rx=\"8\" fill=\"#deede3\"/><text x=\"288\" y=\"103\" font-family=\"Arial\" font-size=\"16\">TRY</text><rect x=\"410\" y=\"55\" width=\"126\" height=\"95\" rx=\"8\" fill=\"#e8ecf7\"/><text x=\"422\" y=\"103\" font-family=\"Arial\" font-size=\"16\">CHECK</text></svg>","alt":"A four-part method for Source Sleuth: Check Evidence and Claims.","caption":"Find, explain, try and check."}],"guided_practice":"First read the model carefully: A source is where information comes from. Record exactly what each source claims before evaluating it. A named specialist team and examples are useful credibility clues. An anonymous caption does not supply expertise or proof. Absolute statements such as ''all bees'' need checking. Compare them with relevant, evidenced sources instead of the loudest post. Say ''This named fact sheet is a stronger starting source'' rather than ''It can never be wrong''. Check information independently.\n\nTry a case from the new challenge and use this feedback to revise your attempt: Authorship, evidence and the breadth of claims matter. One bee seen in a hollow stem cannot prove the nesting habits of every bee species.","independent_task":"Compare three fictional cards: biodiversity team''s illustrated bee nesting guide; anonymous ''ALL bees live in giant hives'' caption; gardener who reports seeing a bee in a hollow stem. Rank usefulness for broad information, identify an observation, explain two credibility clues and a claim that needs checking.","response_prompt":"Compare three fictional cards: biodiversity team''s illustrated bee nesting guide; anonymous ''ALL bees live in giant hives'' caption; gardener who reports seeing a bee in a hollow stem. Rank usefulness for broad information, identify an observation, explain two credibility clues and a claim that needs checking.","quiz":[{"type":"multiple_choice","question":"Which has identifiable authorship?","options":["Biodiversity team","Anonymous caption","Unlabelled screenshot","Unknown rumour"],"correct_index":0,"explanation":"Biodiversity team follows the original source and teaching."},{"type":"multiple_choice","question":"What helps check a claim?","options":["Examples and evidence","Capital letters","Lots of exclamation marks","Anonymity"],"correct_index":0,"explanation":"Examples and evidence follows the original source and teaching."},{"type":"multiple_choice","question":"Which is a sweeping claim?","options":["Every bee lives in a hive","A gardener saw one bee","Some bees visit flowers","A source includes pictures"],"correct_index":0,"explanation":"Every bee lives in a hive follows the original source and teaching."},{"type":"multiple_choice","question":"Which is an observation?","options":["One bee entered a stem","All bees always nest in hives","An invented rule","A guessed global total"],"correct_index":0,"explanation":"One bee entered a stem follows the original source and teaching."},{"type":"multiple_choice","question":"Which is best for a general introduction?","options":["The evidenced team guide","An anonymous caption","A joke","An unsupported headline"],"correct_index":0,"explanation":"The evidenced team guide follows the original source and teaching."},{"type":"multiple_choice","question":"Can one observation prove a universal claim?","options":["No","Yes always","Only on Tuesdays","Only if shared often"],"correct_index":0,"explanation":"No follows the original source and teaching."},{"type":"multiple_choice","question":"What if sources disagree?","options":["Compare specific evidence","Pick the loudest","Ignore both","Assume all are true"],"correct_index":0,"explanation":"Compare specific evidence follows the original source and teaching."},{"type":"multiple_choice","question":"Which conclusion is careful?","options":["A named evidenced source is a better starting point","The loudest source is true","One bee proves all bees behave alike","No source needs checking"],"correct_index":0,"explanation":"A named evidenced source is a better starting point follows the original source and teaching."},{"type":"short_answer","question":"Complete the original source sleuth: check evidence and claims challenge.","sample_answer":"The named biodiversity team''s guide is the strongest starting source for a general explanation; the gardener''s report is a useful single observation; the anonymous universal claim is not supported.","marking_guide":"Look for accurate task-specific evidence and a clear explanation.","explanation":"A complete answer demonstrates the method."},{"type":"short_answer","question":"Explain a specific correction or verification method.","sample_answer":"Authorship, evidence and the breadth of claims matter. One bee seen in a hollow stem cannot prove the nesting habits of every bee species.","marking_guide":"Require relevant detail and correct reasoning.","explanation":"Show why the conclusion follows."}],"parent_notes":"Parent: Ask the learner to show the independent work and explain their reasoning.\n\nParent: Written model 1: The named biodiversity team''s guide is the strongest starting source for a general explanation; the gardener''s report is a useful single observation; the anonymous universal claim is not supported.\n\nParent: Written model 2: Authorship, evidence and the breadth of claims matter. One bee seen in a hollow stem cannot prove the nesting habits of every bee species.\n\nParent: Verify answers, retain evidence and check curriculum alignment separately.","evidence_instructions":"Keep your guided and independent work, along with one correction and written quiz responses.","offline_alternative":"Complete the included examples and challenge on paper; a parent can record oral responses.","extension":"Make a new source sleuth: check evidence and claims challenge and explain the answer.","stage_hints":{"accept":["Read the Source Sleuth: Check Evidence and Claims instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"teach0":["Read the Identify a source and its claim instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"teach1":["Read the Find accountable authorship instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"teach2":["Read the Compare evidence rather than volume instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"teach3":["Read the Make qualified conclusions instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"learn":["Read the Source Sleuth: Check Evidence and Claims instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"guided":["Read the Source Sleuth: Check Evidence and Claims instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"write":["Read the Source Sleuth: Check Evidence and Claims instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"quiz":["Read the Source Sleuth: Check Evidence and Claims instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."],"submit":["Read the Source Sleuth: Check Evidence and Claims instruction.","Point to a relevant number, fact or phrase in the original example.","Explain how your evidence supports the answer and check one mistake."]}}') WHERE seed_key='s2-eng-y3-w07-l4';
UPDATE lessons SET title='Column Addition: Carry and Verify',data=json_patch(data,'{"seed_key":"s2-mat-y3-w07-l1","title":"Column Addition: Carry and Verify","stage":"Stage 2","learning_area":"Mathematics","year_level":3,"week":7,"lesson_number":1,"duration_minutes":60,"child_mission":"Learn column addition: carry and verify through original examples and guided practice before an independent challenge.","learning_intention":"We are learning to explain and apply column addition: carry and verify.","success_criteria":["I can explain the concept.","I can use and explain a worked example.","I can practise and learn from feedback.","I can attempt the independent challenge.","I can verify my answer."],"materials":["Original passages and examples included","Optional paper and pencil or ordinary counters"],"outcome_codes":[],"review_status":"unreviewed","pass":1,"pass_mark":0.9,"coming_soon":null,"source_note":null,"explicit_teaching":null,"resources":null,"sort_activity":null,"word_challenges":null,"suspense_builder":null,"planner_fields":null,"planner_title":null,"planner_intro":null,"spelling":null,"spelling_focus":null,"hoard_words":null,"follow_up_challenges":null,"steps":null,"visual_plan":null,"interactive_activities":[{"type":"flip_cards","title":"Important concepts","cards":[{"front":"Align place values","back":"Write the hundreds, tens and ones under matching places: 268 above 157."},{"front":"Regroup ten ones","back":"8+7=15 ones; write 5 and carry one ten to the next column."},{"front":"Regroup ten tens","back":"6+5+1=12 tens; write 2 tens and carry one hundred. 2+1+1=4 hundreds. The answer is 425."},{"front":"Verify the total","back":"Estimate 270+160≈430 and check exactly with 425−157=268."}]}],"printable_resource":{"title":"Column Addition: Carry and Verify","instructions":"Use the original example to learn, then solve the new task.","passage":"A shelter receives 268 donations on Friday and 157 on Saturday.","prompts":["Find evidence.","Explain the method.","Try the new task.","Check it."]},"reflection_prompts":null,"reflection_prompt":null,"teach_steps":[{"icon":"🔎","title":"Align place values","explain":"**Learn this idea:** Write the hundreds, tens and ones under matching places: 268 above 157.\n\n**Original source:** A shelter receives 268 donations on Friday and 157 on Saturday.\n\nLook for the specific clue or number that proves your conclusion.","example":"**WATCH MY THINKING:** Write the hundreds, tens and ones under matching places: 268 above 157.\n\n**TRY:** Add 376+258, then add 49. Show each carried ten and hundred; estimate using rounding to tens and check your exact final result with inverse subtraction. Explain why 376+258 is 634, not 524.\n\n**CHECK:** Compare your method against the original case and correct any mistaken detail.","notice":"Write the hundreds, tens and ones under matching places: 268 above 157.","check":{"question":"268+157?","options":["415","425","435","525"],"correct_index":1,"explanation":"425: Write the hundreds, tens and ones under matching places: 268 above 157."},"visual_before":[{"episode":{"title":"Column Addition: Carry and Verify: first clue","transcript":"Pip: Eight plus seven equals fifteen; should I write fifteen ones?\nJuno: Write five ones, exchange ten ones for one ten.\nPip: Then six plus five plus the carried one is twelve tens.\nJuno: Pause and exchange ten tens for one hundred before finishing.","scenes":[{"bg":"room","lines":[{"who":"pip","text":"Eight plus seven equals fifteen; should I write fifteen ones?"},{"who":"juno","text":"Write five ones, exchange ten ones for one ten."},{"who":"pip","text":"Then six plus five plus the carried one is twelve tens."},{"who":"juno","text":"Pause and exchange ten tens for one hundred before finishing.","pause_after":true}]}]}}]},{"icon":"📘","title":"Regroup ten ones","explain":"**Learn this idea:** 8+7=15 ones; write 5 and carry one ten to the next column.\n\n**Original source:** A shelter receives 268 donations on Friday and 157 on Saturday.\n\nLook for the specific clue or number that proves your conclusion.","example":"**WATCH MY THINKING:** 8+7=15 ones; write 5 and carry one ten to the next column.\n\n**TRY:** Add 376+258, then add 49. Show each carried ten and hundred; estimate using rounding to tens and check your exact final result with inverse subtraction. Explain why 376+258 is 634, not 524.\n\n**CHECK:** Compare your method against the original case and correct any mistaken detail.","notice":"8+7=15 ones; write 5 and carry one ten to the next column.","check":{"question":"8+7?","options":["14","15","16","5"],"correct_index":1,"explanation":"15: 8+7=15 ones; write 5 and carry one ten to the next column."}},{"icon":"✍️","title":"Regroup ten tens","explain":"**Learn this idea:** 6+5+1=12 tens; write 2 tens and carry one hundred. 2+1+1=4 hundreds. The answer is 425.\n\n**Original source:** A shelter receives 268 donations on Friday and 157 on Saturday.\n\nLook for the specific clue or number that proves your conclusion.","example":"**WATCH MY THINKING:** 6+5+1=12 tens; write 2 tens and carry one hundred. 2+1+1=4 hundreds. The answer is 425.\n\n**TRY:** Add 376+258, then add 49. Show each carried ten and hundred; estimate using rounding to tens and check your exact final result with inverse subtraction. Explain why 376+258 is 634, not 524.\n\n**CHECK:** Compare your method against the original case and correct any mistaken detail.","notice":"6+5+1=12 tens; write 2 tens and carry one hundred. 2+1+1=4 hundreds. The answer is 425.","check":{"question":"Tens total including carried ten?","options":["11","12","13","14"],"correct_index":1,"explanation":"12: 6+5+1=12 tens; write 2 tens and carry one hundred. 2+1+1=4 hundreds. The answer is 425."}},{"icon":"✅","title":"Verify the total","explain":"**Learn this idea:** Estimate 270+160≈430 and check exactly with 425−157=268.\n\n**Original source:** A shelter receives 268 donations on Friday and 157 on Saturday.\n\nLook for the specific clue or number that proves your conclusion.","example":"**WATCH MY THINKING:** Estimate 270+160≈430 and check exactly with 425−157=268.\n\n**TRY:** Add 376+258, then add 49. Show each carried ten and hundred; estimate using rounding to tens and check your exact final result with inverse subtraction. Explain why 376+258 is 634, not 524.\n\n**CHECK:** Compare your method against the original case and correct any mistaken detail.","notice":"Estimate 270+160≈430 and check exactly with 425−157=268.","check":{"question":"146+278?","options":["414","424","434","524"],"correct_index":1,"explanation":"424: Estimate 270+160≈430 and check exactly with 425−157=268."}}],"worked_example":"A shelter receives 268 donations on Friday and 157 on Saturday.\n\n**1. Align place values:** Write the hundreds, tens and ones under matching places: 268 above 157.\n\n**2. Regroup ten ones:** 8+7=15 ones; write 5 and carry one ten to the next column.\n\n**3. Regroup ten tens:** 6+5+1=12 tens; write 2 tens and carry one hundred. 2+1+1=4 hundreds. The answer is 425.\n\n**4. Verify the total:** Estimate 270+160≈430 and check exactly with 425−157=268.","worked_visuals":[{"svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 540 170\"><rect width=\"540\" height=\"170\" rx=\"10\" fill=\"#f4f8f5\"/><text x=\"12\" y=\"30\" font-family=\"Arial\" font-size=\"20\">Addition columns</text><rect x=\"8\" y=\"55\" width=\"126\" height=\"95\" rx=\"8\" fill=\"#deede3\"/><text x=\"20\" y=\"103\" font-family=\"Arial\" font-size=\"16\">FIND</text><rect x=\"142\" y=\"55\" width=\"126\" height=\"95\" rx=\"8\" fill=\"#e8ecf7\"/><text x=\"154\" y=\"103\" font-family=\"Arial\" font-size=\"16\">EXPLAIN</text><rect x=\"276\" y=\"55\" width=\"126\" height=\"95\" rx=\"8\" fill=\"#deede3\"/><text x=\"288\" y=\"103\" font-family=\"Arial\" font-size=\"16\">TRY</text><rect x=\"410\" y=\"55\" width=\"126\" height=\"95\" rx=\"8\" fill=\"#e8ecf7\"/><text x=\"422\" y=\"103\" font-family=\"Arial\" font-size=\"16\">CHECK</text></svg>","alt":"A four-part method for Column Addition: Carry and Verify.","caption":"Find, explain, try and check."}],"guided_practice":"First read the model carefully: Write the hundreds, tens and ones under matching places: 268 above 157. 8+7=15 ones; write 5 and carry one ten to the next column. 6+5+1=12 tens; write 2 tens and carry one hundred. 2+1+1=4 hundreds. The answer is 425. Estimate 270+160≈430 and check exactly with 425−157=268.\n\nTry a case from the new challenge and use this feedback to revise your attempt: 376+258: ones 6+8=14, carry ten; tens 7+5+1=13, carry a hundred; hundreds 3+2+1=6. Subtract 49 from 683 to get 634.","independent_task":"Add 376+258, then add 49. Show each carried ten and hundred; estimate using rounding to tens and check your exact final result with inverse subtraction. Explain why 376+258 is 634, not 524.","response_prompt":"Add 376+258, then add 49. Show each carried ten and hundred; estimate using rounding to tens and check your exact final result with inverse subtraction. Explain why 376+258 is 634, not 524.","quiz":[{"type":"multiple_choice","question":"268+157?","options":["415","425","435","525"],"correct_index":1,"explanation":"425 follows the original source and teaching."},{"type":"multiple_choice","question":"8+7?","options":["14","15","16","5"],"correct_index":1,"explanation":"15 follows the original source and teaching."},{"type":"multiple_choice","question":"Tens total including carried ten?","options":["11","12","13","14"],"correct_index":1,"explanation":"12 follows the original source and teaching."},{"type":"multiple_choice","question":"146+278?","options":["414","424","434","524"],"correct_index":1,"explanation":"424 follows the original source and teaching."},{"type":"multiple_choice","question":"389+47?","options":["426","436","446","536"],"correct_index":1,"explanation":"436 follows the original source and teaching."},{"type":"multiple_choice","question":"376+258?","options":["524","624","634","644"],"correct_